const { execSync } = require('child_process');
try {
    const r = execSync(`sqlite3 -json '/Users/redinside/.openclaw/workspace/data/social-monitoring.db' "SELECT platform, COUNT(*) as count FROM content_raw WHERE captured_at > datetime('now','-24 hours') GROUP BY platform"`, {encoding:'utf8',timeout:5000}).trim();
