parameters.functionCode:
const stats = $input.all()[0].json;
const keywords = $input.all()[1].json;
const alerts = $input.all()[2].json;
const reportDate = $node["Init Run"].json.reportDate;

// Build platform summary
let platformSummary = '';
if (Array.isArray(stats)) {
  platformSummary = stats.map(s => 
    `- **${s.platform}:** ${s.total_posts} posts, avg sentiment ${(s.sentiment_avg || 0).toFixed(2)}, ${s.total_engagement || 0} total engagement`
  ).join('\n');
} else if (stats.platform) {
  platformSummary = `- **${stats.platform}:** ${stats.total_posts} posts, avg sentiment ${(stats.sentiment_avg || 0).toFixed(2)}, ${stats.total_engagement || 0} total engagement`;
} else {
  platformSummary = '- No data collected in the last 24 hours';
}

// Build keywords list
let keywordsList = '';
if (Array.isArray(keywords) && keywords.length > 0) {
  keywordsList = keywords.map((k, i) => `${i+1}. ${k.keyword} (${k.frequency} mentions)`).join('\n');
} else if (keywords.keyword) {
  keywordsList = `1. ${keywords.keyword} (${keywords.frequency} mentions)`;
} else {
  keywordsList = '- No keywords extracted';
}

// Build alerts section
let alertsList = '';
if (Array.isArray(alerts) && alerts.length > 0) {
  alertsList = alerts.map((a, i) => 
    `${i+1}. **${a.platform}** by ${a.author} (${a.engagement_total} engagement)\n   ${a.text.substring(0, 150)}...\n   ${a.url}`
  ).join('\n\n');
} else if (alerts.platform) {
  alertsList = `1. **${alerts.platform}** by ${alerts.author} (${alerts.engagement_total} engagement)\n   ${alerts.text.substring(0, 150)}...\n   ${alerts.url}`;
} else {
  alertsList = '- No negative sentiment alerts in the last 24 hours';
}

const summary = `# Daily Social Monitoring Report — ${reportDate}

## Platform Summary
${platformSummary}

## Top Keywords
${keywordsList}

## Top Negative Sentiment Alerts
${alertsList}

## Actions
- Review alerts in Slack #redos-mission-control
- Check workflow health: http://127.0.0.1:5678

---
*Generated by aggregator-service at ${new Date().toISOString()}*`;

const trends = {
  platforms: Array.isArray(stats) ? stats : [stats],
  keywords: Array.isArray(keywords) ? keywords.slice(0, 5) : [keywords],
  alerts: Array.isArray(alerts) ? alerts : [alerts]
};

return [{
  json: {
    reportDate,
    summary,
    trends: JSON.stringify(trends)
  }
}];
